'use client';

import { Calendar, ChevronDown, Clock, FileText, Users } from 'lucide-react';
import { memo } from 'react';

import { BookingStatusBadge } from '@/components/features/booking-state-machine';
import { Avatar, AvatarFallback } from '@/components/ui/avatar';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { CollapsibleTrigger } from '@/components/ui/collapsible';
import { cn } from '@/lib/utils';

import type { OpsBookingCardHeaderViewModel } from './opsBookingCardUtils';
import type { OpsBookingStatus } from '@/types/ops';

export type OpsBookingCardHeaderProps = {
  header: OpsBookingCardHeaderViewModel;
  isOpen: boolean;
  showCollapseToggle?: boolean;
  disableCollapseToggle?: boolean;
};

export const OpsBookingCardHeader = memo(function OpsBookingCardHeader({
  header,
  isOpen,
  showCollapseToggle = true,
  disableCollapseToggle = false,
}: OpsBookingCardHeaderProps) {
  const {
    bookingId,
    status,
    customerLabel,
    initials,
    partySizeLabel,
    dateLabel,
    timeRangeLabel,
    isDone,
    hasNotes,
    urgency,
  } = header;

  return (
    <div className="p-3 pb-2 sm:p-4 sm:pb-4">
      <div className="mb-2 flex flex-col gap-3 sm:mb-4 sm:flex-row sm:items-start sm:justify-between sm:gap-4">
        <div className="flex min-w-0 gap-3">
          <Avatar>
            <AvatarFallback
              className={cn(
                'text-sm font-semibold',
                isDone ? 'bg-muted/50 text-muted-foreground' : 'bg-muted/60 text-foreground/80',
              )}
            >
              {initials}
            </AvatarFallback>
          </Avatar>
          <div className="min-w-0">
            <div className="flex flex-wrap items-center gap-2">
              <p
                id={`guest-name-${bookingId}`}
                className={cn(
                  'break-words text-[15px] font-semibold leading-tight',
                  isDone
                    ? 'text-muted-foreground line-through decoration-border/60'
                    : 'text-foreground',
                )}
                title={customerLabel}
              >
                {customerLabel}
              </p>
            </div>
            <div className="mt-1 flex flex-col gap-1 text-xs font-medium text-muted-foreground sm:flex-row sm:flex-wrap sm:items-center sm:gap-x-2 sm:gap-y-1.5 sm:text-sm">
              <div className="flex flex-wrap items-center gap-x-2 gap-y-1 sm:contents">
                <span className="inline-flex items-center gap-1.5 whitespace-nowrap">
                  <Users className="h-3.5 w-3.5 shrink-0" aria-hidden />
                  <span>{partySizeLabel}</span>
                </span>
                <span className="inline-flex items-center gap-1.5 whitespace-nowrap">
                  <Calendar className="h-3.5 w-3.5 shrink-0" aria-hidden />
                  <span>{dateLabel}</span>
                </span>
              </div>
              <div className="flex items-center sm:contents">
                <span className="inline-flex items-center gap-1.5 whitespace-nowrap rounded bg-muted/40 px-1.5 py-0.5 font-mono text-[11px] text-muted-foreground">
                  <Clock className="h-3 w-3" aria-hidden />
                  {timeRangeLabel}
                </span>
              </div>
            </div>
          </div>
        </div>

        <div className="flex min-w-0 flex-wrap items-start justify-between gap-2 sm:w-auto sm:shrink-0 sm:flex-col sm:items-end sm:justify-start sm:gap-1.5">
          <div className="flex items-center gap-2">
            <BookingStatusBadge status={status as OpsBookingStatus} size="sm" showTooltip={false} />
            {showCollapseToggle ? (
              <CollapsibleTrigger asChild className="sm:hidden">
                <Button
                  variant="ghost"
                  size="sm"
                  className="h-9 w-9 rounded-full p-0 transition-colors duration-150 hover:bg-muted/60 focus-visible:ring-[3px] focus-visible:ring-ring/30 motion-reduce:transition-none"
                  aria-expanded={isOpen}
                  aria-controls={`ops-booking-details-${bookingId}`}
                  disabled={disableCollapseToggle}
                >
                  <ChevronDown
                    className={cn(
                      'h-4 w-4 text-muted-foreground transition-transform duration-150 ease-out motion-reduce:transition-none',
                      isOpen && 'rotate-180',
                    )}
                  />
                  <span className="sr-only">Toggle details</span>
                </Button>
              </CollapsibleTrigger>
            ) : null}
          </div>
          {showCollapseToggle && !isOpen && hasNotes ? (
            <Badge variant="secondary" className="sm:hidden">
              <FileText className="mr-1 h-3 w-3" aria-hidden />
              Notes
              <span className="sr-only"> available. Expand details to read.</span>
            </Badge>
          ) : null}
          {urgency ? (
            <Badge
              variant={urgency.variant === 'destructive' ? 'destructive' : 'outline'}
              className={cn(
                'max-w-full py-0.5 text-xs uppercase tracking-wider',
                urgency.variant === 'warning' && 'border-primary/30 bg-primary/10 text-primary',
              )}
            >
              <Clock className="mr-1 h-3 w-3" aria-hidden /> {urgency.label}
            </Badge>
          ) : null}
        </div>
      </div>
    </div>
  );
});

OpsBookingCardHeader.displayName = 'OpsBookingCardHeader';

'use client';

import { AlertTriangle, Armchair, FileText, Mail, Phone, Users } from 'lucide-react';
import { memo } from 'react';

import { CollapsibleContent } from '@/components/ui/collapsible';
import { cn } from '@/lib/utils';

import type { OpsBookingCardDetailsViewModel } from './opsBookingCardUtils';
import type { ElementType, ReactNode } from 'react';

const InfoTile = ({
  label,
  children,
  icon: Icon,
  className,
}: {
  label: string;
  children: ReactNode;
  icon?: ElementType;
  className?: string;
}) => (
  <div
    className={cn(
      'flex flex-col gap-1 rounded-lg border border-border/60 bg-muted/20 p-2.5',
      className,
    )}
  >
    <div className="flex items-center gap-1.5 text-xs font-semibold uppercase tracking-wider text-muted-foreground">
      {Icon ? <Icon className="h-3 w-3" aria-hidden /> : null}
      {label}
    </div>
    <div className="text-[13px] leading-snug">{children}</div>
  </div>
);

export type OpsBookingCardDetailsProps = {
  details: OpsBookingCardDetailsViewModel;
};

export const OpsBookingCardDetails = memo(function OpsBookingCardDetails({
  details,
}: OpsBookingCardDetailsProps) {
  const { bookingId, reference, table, contact, notes } = details;

  const content = (
    <div className="grid grid-cols-1 gap-2 pb-4 sm:grid-cols-2 lg:grid-cols-4">
      <InfoTile label="Table" icon={Armchair}>
        {table.state === 'assigned' ? (
          <span className="font-semibold text-foreground">{table.label}</span>
        ) : table.state === 'done-empty' ? (
          <span className="italic text-muted-foreground">N/A</span>
        ) : (
          <span className="flex items-center gap-1 font-semibold text-primary">
            <AlertTriangle className="h-3.5 w-3.5" aria-hidden /> {table.label}
          </span>
        )}
      </InfoTile>

      <InfoTile label={contact.label} icon={Mail}>
        <div className="flex flex-col gap-1 overflow-hidden leading-tight">
          {contact.phone ? (
            <span className="flex items-center gap-1 break-words text-xs font-semibold text-foreground/80">
              <Phone className="h-2.5 w-2.5 shrink-0" aria-hidden /> {contact.phone}
            </span>
          ) : null}
          {contact.email ? (
            <span
              className="break-all text-xs italic leading-[1.1] text-muted-foreground/70"
              title={contact.email}
            >
              {contact.email}
            </span>
          ) : null}
          {!contact.phone && !contact.email ? (
            <span className="text-xs italic text-muted-foreground">{contact.emptyLabel}</span>
          ) : null}
        </div>
      </InfoTile>

      <InfoTile label={reference.label} icon={Users}>
        <div className="flex flex-col">
          <span className="break-all font-mono text-xs text-muted-foreground">{reference.valueLabel}</span>
        </div>
      </InfoTile>

      <InfoTile
        label={notes.label}
        icon={FileText}
        className={cn(notes.highlighted && 'border-primary/30 bg-primary/10')}
      >
        <p className="break-words text-xs italic text-muted-foreground">{notes.value}</p>
      </InfoTile>
    </div>
  );

  return (
    <CollapsibleContent
      forceMount
      id={`ops-booking-details-${bookingId}`}
      className="px-4 data-[state=closed]:hidden sm:block sm:data-[state=closed]:block"
    >
      {content}
    </CollapsibleContent>
  );
});

OpsBookingCardDetails.displayName = 'OpsBookingCardDetails';

'use client';

import { Check, Loader2, LogIn, LogOut, MoreHorizontal } from 'lucide-react';
import { memo, useCallback, useState } from 'react';

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog';
import { Button } from '@/components/ui/button';
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { cn } from '@/lib/utils';

import type { OpsBookingCardActionsViewModel } from './opsBookingCardUtils';

export type OpsBookingCardActionsProps = {
  actions: OpsBookingCardActionsViewModel;
  onDetails?: () => void;
  onEdit?: () => void;
  onCancel?: () => void;
  onMarkNoShow?: (bookingId: string) => Promise<void>;
  onCheckIn?: (bookingId: string) => Promise<void>;
  onCheckOut?: (bookingId: string) => Promise<void>;
};

export const OpsBookingCardActions = memo(function OpsBookingCardActions({
  actions,
  onDetails,
  onEdit,
  onCancel,
  onMarkNoShow,
  onCheckIn,
  onCheckOut,
}: OpsBookingCardActionsProps) {
  const [isNoShowOpen, setIsNoShowOpen] = useState(false);
  const isNoShowPending = actions.noShowConfirmation.pending;
  const partySize = actions.noShowConfirmation.description.partySize;
  const primaryButton = actions.primary.kind === 'button' ? actions.primary : null;
  const disableMenuTrigger =
    actions.details.disabled && actions.menuItems.every((item) => item.disabled);

  const handleConfirmNoShow = useCallback(async () => {
    try {
      await onMarkNoShow?.(actions.bookingId);
    } finally {
      setIsNoShowOpen(false);
    }
  }, [actions.bookingId, onMarkNoShow]);

  return (
    <div className="px-4 pb-4">
      <div className="flex flex-wrap items-center justify-between gap-y-3 border-t border-border/60 pt-3">
        <div className="flex items-center gap-1">
          <Button
            variant="outline"
            size="sm"
            className="h-9 px-4 text-xs font-medium focus-visible:ring-[3px] focus-visible:ring-ring/30 sm:h-8"
            onClick={onDetails}
            disabled={actions.details.disabled}
          >
            {actions.details.label}
          </Button>

          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="sm"
                className="h-9 w-9 p-0 focus-visible:ring-[3px] focus-visible:ring-ring/30 sm:h-8 sm:w-8"
                aria-label="More actions"
                disabled={disableMenuTrigger}
              >
                <MoreHorizontal className="h-4 w-4" aria-hidden />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="start">
              <DropdownMenuLabel className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">
                Manage
              </DropdownMenuLabel>
              <DropdownMenuSeparator />
              <DropdownMenuItem onClick={onEdit} disabled={actions.menuItems[0].disabled}>
                {actions.menuItems[0].label}
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => setIsNoShowOpen(true)}
                disabled={actions.menuItems[1].disabled}
                variant="destructive"
              >
                {actions.menuItems[1].label}
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                onClick={onCancel}
                disabled={actions.menuItems[2].disabled}
                variant="destructive"
              >
                {actions.menuItems[2].label}
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        <div>
          {primaryButton ? (
            <Button
              size="sm"
              disabled={primaryButton.disabled}
              className={cn(
                'h-9 w-full sm:w-auto sm:min-w-[120px] px-6 font-semibold shadow-sm transition-[box-shadow,background-color] duration-150 ease-out hover:shadow-sm motion-reduce:transition-none',
                primaryButton.id === 'check-out'
                  ? 'bg-muted/40 text-muted-foreground hover:bg-muted'
                  : 'bg-primary/10 text-primary hover:bg-primary/10',
              )}
              onClick={() =>
                primaryButton.id === 'check-out'
                  ? onCheckOut?.(actions.bookingId)
                  : onCheckIn?.(actions.bookingId)
              }
            >
              {primaryButton.pending ? (
                <>
                  <Loader2 className="mr-2 h-4 w-4 animate-spin" aria-hidden /> Updating…
                </>
              ) : primaryButton.id === 'check-out' ? (
                <>
                  <LogOut className="mr-2 h-4 w-4" aria-hidden /> Finish
                </>
              ) : (
                <>
                  <LogIn className="mr-2 h-4 w-4" aria-hidden /> Seat Guest
                </>
              )}
            </Button>
          ) : (
            <div
              className="flex items-center gap-1.5 px-3 text-xs font-bold text-muted-foreground"
              role="status"
            >
              <Check className="h-4 w-4 text-primary" aria-hidden />
              {actions.primary.label}
            </div>
          )}
        </div>
      </div>

      <AlertDialog open={isNoShowOpen} onOpenChange={setIsNoShowOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>{actions.noShowConfirmation.title}</AlertDialogTitle>
            <AlertDialogDescription>
              You’re about to mark{' '}
              <span className="font-semibold text-foreground">
                {actions.noShowConfirmation.description.customerLabel}
              </span>{' '}
              as a no-show for <span className="font-semibold text-foreground">{partySize}</span>{' '}
              cover{partySize === 1 ? '' : 's'} on{' '}
              <span className="font-semibold text-foreground">
                {actions.noShowConfirmation.description.dateLabel} ·{' '}
                {actions.noShowConfirmation.description.timeRangeLabel}
              </span>
              . You can undo this shortly after confirming.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel disabled={actions.noShowConfirmation.disabled || isNoShowPending}>
              {actions.noShowConfirmation.cancelLabel}
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => void handleConfirmNoShow()}
              className="bg-destructive/10 text-destructive hover:bg-destructive/10"
              disabled={actions.noShowConfirmation.disabled || isNoShowPending}
            >
              {isNoShowPending ? 'Marking…' : actions.noShowConfirmation.confirmLabel}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
});

OpsBookingCardActions.displayName = 'OpsBookingCardActions';

import type { BookingDTO } from '@/hooks/useBookings';
import type { OpsBookingStatus } from '@/types/ops';

export type NormalizedGuestIdentity = {
  label: string;
  initials: string;
  isWalkInGuest: boolean;
};

export type BookingMeta = {
  startDate: Date;
  isToday: boolean;
  isPastDay: boolean;
  isDone: boolean;
  isSeated: boolean;
  guest: NormalizedGuestIdentity;
  customerLabel: string;
  initials: string;
  dateLabel: string;
  timeRangeLabel: string;
};

export type UrgencyBadge = {
  variant: 'destructive' | 'warning';
  label: string;
};

export type OpsBookingCardPendingAction =
  | 'check-in'
  | 'check-out'
  | 'no-show'
  | 'undo-no-show'
  | null;

export type OpsBookingCardHeaderViewModel = {
  bookingId: string;
  status: OpsBookingStatus;
  customerLabel: string;
  initials: string;
  partySizeLabel: string;
  dateLabel: string;
  timeRangeLabel: string;
  isDone: boolean;
  hasNotes: boolean;
  urgency: UrgencyBadge | null;
};

export type OpsBookingCardDetailsViewModel = {
  bookingId: string;
  reference: {
    label: string;
    valueLabel: string;
  };
  table: {
    state: 'assigned' | 'done-empty' | 'unassigned';
    label: string;
  };
  contact: {
    label: string;
    phone: string | null;
    email: string | null;
    emptyLabel: string;
  };
  notes: {
    label: string;
    value: string;
    highlighted: boolean;
  };
};

export type OpsBookingCardActionPolicyItem = {
  id: 'details' | 'edit' | 'no-show' | 'cancel';
  label: string;
  disabled: boolean;
  valid: boolean;
  variant?: 'default' | 'destructive';
};

export type OpsBookingCardPrimaryActionPolicy =
  | {
      kind: 'button';
      id: 'check-in' | 'check-out';
      label: string;
      disabled: boolean;
      valid: boolean;
      pending: boolean;
    }
  | {
      kind: 'status';
      label: string;
    };

export type OpsBookingCardActionsViewModel = {
  bookingId: string;
  pendingAction: OpsBookingCardPendingAction;
  details: OpsBookingCardActionPolicyItem;
  menuItems: [
    OpsBookingCardActionPolicyItem,
    OpsBookingCardActionPolicyItem,
    OpsBookingCardActionPolicyItem,
  ];
  primary: OpsBookingCardPrimaryActionPolicy;
  noShowConfirmation: {
    title: string;
    description: {
      customerLabel: string;
      partySize: number;
      dateLabel: string;
      timeRangeLabel: string;
    };
    confirmLabel: string;
    cancelLabel: string;
    disabled: boolean;
    pending: boolean;
  };
};

export type OpsBookingCardViewModel = {
  booking: BookingDTO;
  meta: BookingMeta;
  urgency: UrgencyBadge | null;
  tableLabel: string | null;
  pendingAction: OpsBookingCardPendingAction;
  disableActions: boolean;
  header: OpsBookingCardHeaderViewModel;
  details: OpsBookingCardDetailsViewModel;
  actions: OpsBookingCardActionsViewModel;
};

const formatterCache = new Map<string, Intl.DateTimeFormat>();

function getFormatter(
  cacheKey: string,
  options: Intl.DateTimeFormatOptions,
  timeZone: string,
): Intl.DateTimeFormat {
  const key = `${cacheKey}:${timeZone}`;
  const existing = formatterCache.get(key);
  if (existing) return existing;
  const formatter = new Intl.DateTimeFormat('en-US', {
    timeZone,
    ...options,
  });
  formatterCache.set(key, formatter);
  return formatter;
}

function getDateKey(date: Date, timeZone: string): string {
  const formatter = getFormatter(
    'ops-card-date-key',
    { year: 'numeric', month: '2-digit', day: '2-digit' },
    timeZone,
  );
  const parts = formatter.formatToParts(date);
  const year = parts.find((part) => part.type === 'year')?.value ?? '0000';
  const month = parts.find((part) => part.type === 'month')?.value ?? '01';
  const day = parts.find((part) => part.type === 'day')?.value ?? '01';
  return `${year}-${month}-${day}`;
}

function normalizeText(value: string | null | undefined): string | null {
  const trimmed = value?.trim();
  return trimmed ? trimmed : null;
}

export function getTableLabel(assignments: BookingDTO['tableAssignments']) {
  if (!assignments || assignments.length === 0) {
    return null;
  }

  const labels: string[] = [];
  for (const group of assignments) {
    const members = group.members ?? [];
    const memberLabels = members.map((member) => member.tableNumber || '—');
    labels.push(memberLabels.join(' + '));
  }
  return labels.join(', ');
}

function getGuestIdentity(booking: BookingDTO): NormalizedGuestIdentity {
  const label =
    normalizeText(booking.displayCustomerLabel) ??
    normalizeText(booking.customerName) ??
    'Walk-in Guest';
  const displayInitials = normalizeText(booking.displayInitials);

  const initials = label
    .split(/\s+/)
    .filter(Boolean)
    .map((part) => part[0] ?? '')
    .join('')
    .toUpperCase()
    .slice(0, 2);

  return {
    label,
    initials: displayInitials ?? (initials || 'WG'),
    isWalkInGuest: label === 'Walk-in Guest',
  };
}

export function buildBookingMeta(
  booking: BookingDTO,
  timezone: string,
  now: Date,
  timeLabelOverride?: string | null,
): BookingMeta {
  const startDate = new Date(booking.startIso);
  const endDate = booking.endIso ? new Date(booking.endIso) : null;

  const timeFormatter = getFormatter(
    'ops-card-time',
    {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true,
    },
    timezone,
  );
  const dateFormatter = getFormatter(
    'ops-card-date',
    {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
    },
    timezone,
  );

  const startTimeStr = timeFormatter.format(startDate);
  const endTimeStr = endDate ? timeFormatter.format(endDate) : null;

  const startKey = getDateKey(startDate, timezone);
  const nowKey = getDateKey(now, timezone);
  const isToday = startKey === nowKey;
  const isPastDay = startKey < nowKey;

  const isDone = ['completed', 'cancelled', 'no_show'].includes(booking.status);
  const isSeated = booking.status === 'checked_in';
  const guest = getGuestIdentity(booking);
  const timeRangeLabel =
    normalizeText(timeLabelOverride ?? null) ??
    normalizeText(booking.displayTimeRangeLabel) ??
    (endTimeStr ? `${startTimeStr} – ${endTimeStr}` : startTimeStr);

  return {
    startDate,
    isToday,
    isPastDay,
    isDone,
    isSeated,
    guest,
    customerLabel: guest.label,
    initials: guest.initials,
    dateLabel: dateFormatter.format(startDate),
    timeRangeLabel,
  };
}

export function getUrgencyBadge(
  meta: BookingMeta,
  now: Date,
  highlightUrgency: boolean,
): UrgencyBadge | null {
  if (!highlightUrgency || meta.isDone || meta.isSeated || !meta.isToday) return null;
  const diffMinutes = Math.floor((meta.startDate.getTime() - now.getTime()) / 60000);

  if (diffMinutes <= -15) {
    return { variant: 'destructive', label: `${Math.abs(diffMinutes)}m late` };
  }
  if (diffMinutes <= 0) {
    return { variant: 'warning', label: 'Overdue' };
  }
  return null;
}

function getTableDetails(
  tableLabel: string | null,
  isDone: boolean,
): OpsBookingCardDetailsViewModel['table'] {
  if (tableLabel) {
    return {
      state: 'assigned',
      label: `Table ${tableLabel}`,
    };
  }

  if (isDone) {
    return {
      state: 'done-empty',
      label: 'N/A',
    };
  }

  return {
    state: 'unassigned',
    label: 'Unassigned',
  };
}

function buildOpsBookingCardActionPolicy(params: {
  booking: BookingDTO;
  meta: BookingMeta;
  pendingAction: OpsBookingCardPendingAction;
  actionsDisabled: boolean;
}): OpsBookingCardActionsViewModel {
  const { booking, meta, pendingAction, actionsDisabled } = params;
  const isPendingMutation = pendingAction !== null;
  const isMutatingDisabled = actionsDisabled || isPendingMutation;
  const detailsDisabled = isMutatingDisabled;

  const editValid = !meta.isDone && !meta.isPastDay;
  const noShowValid = !meta.isDone && meta.isToday && !meta.isSeated;
  const cancelValid = !meta.isDone && !meta.isPastDay;

  const details: OpsBookingCardActionPolicyItem = {
    id: 'details',
    label: 'Details',
    disabled: detailsDisabled,
    valid: true,
    variant: 'default',
  };

  const menuItems: OpsBookingCardActionsViewModel['menuItems'] = [
    {
      id: 'edit',
      label: 'Edit Booking',
      disabled: !editValid || isMutatingDisabled,
      valid: editValid,
      variant: 'default',
    },
    {
      id: 'no-show',
      label: 'Mark No Show',
      disabled: !noShowValid || isMutatingDisabled,
      valid: noShowValid,
      variant: 'destructive',
    },
    {
      id: 'cancel',
      label: 'Cancel Booking',
      disabled: !cancelValid || isMutatingDisabled,
      valid: cancelValid,
      variant: 'destructive',
    },
  ];

  const primary: OpsBookingCardPrimaryActionPolicy = meta.isDone
    ? {
        kind: 'status',
        label:
          booking.status === 'completed'
            ? 'Completed'
            : booking.status === 'cancelled'
              ? 'Cancelled'
              : booking.status === 'no_show'
                ? 'No show'
                : 'Closed',
      }
    : {
        kind: 'button',
        id: meta.isSeated ? 'check-out' : 'check-in',
        label: meta.isSeated ? 'Finish' : 'Seat Guest',
        disabled: !meta.isToday || isMutatingDisabled,
        valid: meta.isToday,
        pending: pendingAction === 'check-in' || pendingAction === 'check-out',
      };

  return {
    bookingId: booking.id,
    pendingAction,
    details,
    menuItems,
    primary,
    noShowConfirmation: {
      title: 'Mark as no-show?',
      description: {
        customerLabel: meta.customerLabel,
        partySize: booking.partySize,
        dateLabel: meta.dateLabel,
        timeRangeLabel: meta.timeRangeLabel,
      },
      confirmLabel: 'Confirm no-show',
      cancelLabel: 'Keep booking',
      disabled: menuItems[1].disabled,
      pending: pendingAction === 'no-show',
    },
  };
}

export function buildOpsBookingCardViewModel(params: {
  booking: BookingDTO;
  timezone: string;
  now: Date;
  pendingAction?: OpsBookingCardPendingAction;
  actionsDisabled: boolean;
  highlightUrgency?: boolean;
  timeLabelOverride?: string | null;
}): OpsBookingCardViewModel {
  const {
    booking,
    timezone,
    now,
    pendingAction = null,
    actionsDisabled,
    highlightUrgency = true,
    timeLabelOverride,
  } = params;

  const normalizedBooking: BookingDTO = {
    ...booking,
    customerName: normalizeText(booking.customerName),
    customerEmail: normalizeText(booking.customerEmail),
    customerPhone: normalizeText(booking.customerPhone),
    notes: normalizeText(booking.notes),
    reference: normalizeText(booking.reference),
    displayTimeRangeLabel: normalizeText(booking.displayTimeRangeLabel),
    displayCustomerLabel: normalizeText(booking.displayCustomerLabel),
    displayInitials: normalizeText(booking.displayInitials),
    tableLabel: normalizeText(booking.tableLabel),
  };

  const meta = buildBookingMeta(normalizedBooking, timezone, now, timeLabelOverride);
  const urgency = getUrgencyBadge(meta, now, highlightUrgency);
  const tableLabel =
    normalizedBooking.tableLabel ?? getTableLabel(normalizedBooking.tableAssignments);
  const header: OpsBookingCardHeaderViewModel = {
    bookingId: normalizedBooking.id,
    status: normalizedBooking.status,
    customerLabel: meta.customerLabel,
    initials: meta.initials,
    partySizeLabel: `${normalizedBooking.partySize} Guest${normalizedBooking.partySize === 1 ? '' : 's'}`,
    dateLabel: meta.dateLabel,
    timeRangeLabel: meta.timeRangeLabel,
    isDone: meta.isDone,
    hasNotes: Boolean(normalizedBooking.notes),
    urgency,
  };
  const details: OpsBookingCardDetailsViewModel = {
    bookingId: normalizedBooking.id,
    reference: {
      label: 'Reference',
      valueLabel: `Ref ${normalizedBooking.reference ?? normalizedBooking.id.slice(0, 8)}`,
    },
    table: getTableDetails(tableLabel, meta.isDone),
    contact: {
      label: 'Contact',
      phone: normalizedBooking.customerPhone ?? null,
      email: normalizedBooking.customerEmail ?? null,
      emptyLabel: 'No contact',
    },
    notes: {
      label: 'Notes',
      value: normalizedBooking.notes ?? 'No special requests.',
      highlighted: Boolean(normalizedBooking.notes),
    },
  };
  const actions = buildOpsBookingCardActionPolicy({
    booking: normalizedBooking,
    meta,
    pendingAction,
    actionsDisabled,
  });

  return {
    booking: normalizedBooking,
    meta,
    urgency,
    tableLabel,
    pendingAction,
    disableActions: actionsDisabled,
    header,
    details,
    actions,
  };
}
